const qs = [
  ["proto", "rg -n \"rpc (CreateMemo|ListMemos|SignIn|Transcribe)|service |google.api.http\" proto/api/v1"],
  ["store", "rg -n \"type (Store|Memo|Postgres|SQLite|Mysql|MySQL)|func .*CreateMemo|func .*GetUser|DeleteMemo|New.*Store|New.*Driver|interface\" store store/db"],
  ["frontend", "rg -n \"create.*Client|MemoService|use.*Memo|ListMemos|CreateMemo|auth.*intercept|interceptor|webhook|runner|cron|schedule\" web server internal | head -300"],
  ["migrations", "rg --files store/migration store/seed | sort"],
  ["server", "rg -n \"Register.*Memo|MemoService|ServeHTTP|embed|go:embed|SSE|Broadcast|webhook|Dispatch|runner|Run\\(\" server internal | head -400"]
];
const out = await Promise.all(qs.map(async ([n,cmd]) => [n, await tools.exec_command({cmd,workdir:"/bench/repo",yield_time_ms:10000,max_output_tokens:16000})]));
for (const [n,r] of out) { text(`===${n}===\n${r.output}`); }

