const cmds=[
"rg -n '^type .* interface|Store\\.GetUser|\\.GetUser\\(' --glob '*.go' .",
"rg -n '^func \\(s \\*APIV1Service\\) (CreateMemo|ListMemos|GetMemo|UpdateMemo|DeleteMemo|SetMemoAttachments|SetMemoRelations)|Store\\.CreateMemo|Store\\.DeleteMemo' server/router/api/v1 --glob '*.go'",
"rg -n '^func \\(s \\*APIV1Service\\) (Create|Get|List|Update|Delete).*Shortcut|func \\(s \\*APIV1Service\\).*Shortcut' server/router/api/v1 --glob '*.go'; rg -n '^  rpc ' proto/api/v1/shortcut_service.proto",
"rg -n 'type (User|Attachment|Reaction) struct' store; rg -n 'func \\(s \\*Store\\) (ListMemos|CreateMemo|DeleteMemo)|INSERT INTO memo|DELETE FROM memo' store --glob '*.go'",
"rg -n 'DispatchMemo|PostAsync|HMAC|sha256|signature|Sign' server/router/api/v1 internal/webhook --glob '*.go'"
];
const out=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/bench/repo",yield_time_ms:10000,max_output_tokens:12000})));
for(const r of out) text(r.output+"\n---\n");

